package com.bank.mdm;

import java.util.*;
import java.util.logging.Logger;

public class CustomerProfileMerger {

    private static final Logger log = Logger.getLogger(CustomerProfileMerger.class.getName());
    private int[] parent;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra != rb) parent[ra] = rb;
    }

    public List<List<String>> merge(List<List<String>> accounts) {
        Map<String, Integer> emailToId = new HashMap<>();
        Map<String, String> emailToName = new HashMap<>();
        for (List<String> acc : accounts) {
            String name = acc.get(0);
            for (int i = 1; i < acc.size(); i++) {
                String email = acc.get(i);
                emailToId.putIfAbsent(email, emailToId.size());
                emailToName.put(email, name);
            }
        }
        parent = new int[emailToId.size()];
        for (int i = 0; i < parent.length; i++) parent[i] = i;

        for (List<String> acc : accounts) {
            int firstId = emailToId.get(acc.get(1));
            for (int i = 2; i < acc.size(); i++) {
                union(firstId, emailToId.get(acc.get(i)));
            }
        }
        Map<Integer, TreeSet<String>> grouped = new HashMap<>();
        for (var e : emailToId.entrySet()) {
            int root = find(e.getValue());
            grouped.computeIfAbsent(root, k -> new TreeSet<>()).add(e.getKey());
        }
        List<List<String>> result = new ArrayList<>();
        for (var entry : grouped.entrySet()) {
            List<String> merged = new ArrayList<>();
            String name = emailToName.get(entry.getValue().first());
            merged.add(name);
            merged.addAll(entry.getValue());
            result.add(merged);
        }
        log.info(() -> "Merged into " + result.size() + " golden profiles");
        return result;
    }
}
