package com.bank.mdm;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ProfileMergeDemo {

    private static final Logger log = Logger.getLogger(ProfileMergeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Customer Profile Merge (MDM)");
        List<List<String>> accounts = List.of(
            List.of("Rajesh", "rajesh@nbi.in", "raj@nbi.in"),
            List.of("Rajesh", "raj@nbi.in", "rajesh.kumar@nbi.in"),
            List.of("Priya", "priya@nbi.in")
        );
        CustomerProfileMerger merger = new CustomerProfileMerger();
        merger.merge(accounts).forEach(p -> log.info("Profile: " + p));
    }
}
